// Generated by vibelang from src/prompt/traits.ts; the migrate flow writes it again with each batch.
/** The managed textarea keymap owns `suspend`; these traits only describe capture and status. */
export function computePromptTraits(input) {
    const capture = input.mode === "normal"
        ? input.autocompleteVisible
            ? ["escape", "navigate", "submit", "tab"]
            : ["tab"]
        : undefined;
    return {
        capture,
        status: input.mode === "shell" ? "SHELL" : undefined,
        owner: "opencode",
        role: "prompt",
    };
}
